// Walidacja polskiego numeru IBAN
const iban = (input.iban || '').replace(/\s/g, '');

if (!iban.startsWith('PL')) {
  return {
    valid: false,
    error: 'IBAN musi zaczynać się od PL'
  };
}

if (iban.length !== 28) {
  return {
    valid: false,
    error: `IBAN ma ${iban.length} znaków, powinien mieć 28`
  };
}

const numbers = iban.slice(4) + '2521' + iban.slice(2, 4);
let checksum = BigInt(numbers);
const mod97 = checksum % 97n;

return {
  valid: mod97 === 1n,
  iban: iban,
  formatted: iban.match(/.{1,4}/g).join(' '),
  checksum_valid: mod97 === 1n
};

// Parsowanie i walidacja dat
const dateStr = input.date_string;

// Obsługa różnych formatów polskich dat
const patterns = [
  /^(\d{4})-(\d{2})-(\d{2})$/,  // YYYY-MM-DD
  /^(\d{2})\.(\d{2})\.(\d{4})$/,  // DD.MM.YYYY
  /^(\d{2})\/(\d{2})\/(\d{4})$/,  // DD/MM/YYYY
  /^(\d{2})-(\d{2})-(\d{4})$/   // DD-MM-YYYY
];

for (const pattern of patterns) {
  const match = dateStr.match(pattern);
  if (match) {
    let year, month, day;

    if (match[1].length === 4) {
      // YYYY-MM-DD format
      [, year, month, day] = match;
    } else {
      // DD.MM.YYYY format
      [, day, month, year] = match;
    }

    const date = new Date(`${year}-${month}-${day}`);

    if (!isNaN(date.getTime())) {
      return {
        valid: true,
        original: dateStr,
        parsed: `${year}-${month.padStart(2, '0')}-${day.padStart(2, '0')}`,
        iso_format: date.toISOString().split('T')[0],
        day_of_week: date.toLocaleDateString('pl-PL', { weekday: 'long' })
      };
    }
  }
}

return {
  valid: false,
  original: dateStr,
  error: 'Nierozpoznany format daty'
};
